package io.knowledgebrain.notification;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class NotificationApiTest {
 NotificationStore store;SpaceAuthorizationClient auth;NotificationController api;UUID space,id,actor;
 @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();store=mock(NotificationStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);api=new NotificationController(store,auth,"https://localhost:8443",new SimpleMeterRegistry());}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/notifications/"+id);r.setSecure(true);r.setContentType("application/json");r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"nt1\"");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void writesRequireExactBooleanJsonAndIndependentStrongVersion()throws Exception{for(String body:List.of("{}","{\"read\":1}","{\"read\":\"true\"}","{\"read\":true} {}","{\"read\":true,\"read\":false}","{\"read\":true,\"spaceId\":null}"))assertThrows(ResponseStatusException.class,()->api.read(space.toString(),id.toString(),r("PUT",body)));var missing=r("PUT","{\"read\":true}");missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.read(space.toString(),id.toString(),missing)).getStatusCode().value());for(String tag:List.of("\"dp1\"","\"nt01\"","W/\"nt1\"","*")){var request=r("PUT","{\"read\":true}");request.removeHeader("If-Match");request.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.read(space.toString(),id.toString(),request));}verifyNoInteractions(store);}
 @Test void readsUseFreshCommonAuthorityAndCannotCachePrivateResults(){var value=new NotificationStore.Notification(id,space,"PRIVATE","ACTIVE",1,false,null,actor,Instant.now().toString(),Instant.now().toString());when(store.get(space,id)).thenReturn(value);for(int n=0;n<2;n++){var response=api.get(space.toString(),id.toString(),r("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"nt1\"",response.getHeaders().getETag());}verify(auth,times(2)).authorize(eq(space),any(),eq(false),anyString());reset(store);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET",null)));verifyNoInteractions(store);}
 @Test void crossOriginAndAmbiguousCredentialsUnknownQueriesAndReadBodiesAreDenied(){var cross=r("DELETE",null);cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.retire(space.toString(),id.toString(),cross)).getStatusCode().value());var duplicate=r("GET",null);duplicate.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertEquals(401,assertThrows(ResponseStatusException.class,()->api.list(space.toString(),duplicate)).getStatusCode().value());var query=r("GET",null);query.addParameter("actor","spoof");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),query));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET","{}")));verifyNoInteractions(store);}
}
